scenario.en:
const filters = { status, range };        // new identity every render

// Variant A — synchronous
useEffect(() => {
  setRows(applyFilters(data, filters));   // applyFilters returns a new array
}, [data, filters]);

// Variant B — async
useEffect(() => {
  fetchAndFilter(data, filters)
    .then((rows) => setRows(rows));
}, [data, filters]);

scenario.ru:
// Какой вариант упадёт громко, а какой будет крутиться тихо?
const filters = { status, range };        // новая идентичность на каждом рендере

// Вариант А — синхронный
useEffect(() => {
  setRows(applyFilters(data, filters));   // applyFilters возвращает новый массив
}, [data, filters]);

// Вариант Б — асинхронный
useEffect(() => {
  fetchAndFilter(data, filters)
    .then((rows) => setRows(rows));
}, [data, filters]);
